def encode_shift(s: str) -> str:
    """
    Returns an encoded string by shifting every lowercase alphabetic character
    by 5 positions forward in the alphabet (wrapping around from 'z' to 'a').

    Non‑alphabetic characters are left unchanged.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            # Shift forward by 5 with wrap‑around.
            shifted = ((ord(ch) - ord('a') + 5) % 26) + ord('a')
            result.append(chr(shifted))
        else:
            result.append(ch)
    return "".join(result)


